{
  "name": "ctx-cache-band",
  "version": "0.1.0",
  "author": {
    "name": "Greg Pajak"
  },
  "description": "Band above the prompt: context window used/max and prompt-cache TTL countdown + hit rate; optional auto-compact just before the cache expires.",
  "types": "./types/index.d.ts",
  "userConfig": {
    "cacheTtlMinutes": {
      "type": "string",
      "title": "Prompt cache TTL (minutes)",
      "description": "5 or 60. Must match the TTL your account/session actually uses.",
      "options": [
        "5",
        "60"
      ],
      "default": "60"
    },
    "autoCompact": {
      "type": "boolean",
      "title": "Auto-compact before cache expiry",
      "description": "Run /compact while the cache is still warm, so the idle-expiry re-cache is paid on a small context instead of the full one.",
      "default": true
    },
    "compactLeadMinutes": {
      "type": "number",
      "title": "Compact when this many minutes of cache remain",
      "description": "Auto-compact fires once per idle window when remaining TTL drops to this.",
      "default": 3
    },
    "minCompactTokens": {
      "type": "number",
      "title": "Only auto-compact above this many context tokens",
      "description": "Below this, re-caching on return is cheap and compaction only loses detail.",
      "default": 150000
    }
  }
}

